const updateRuleSet = `-- name: UpdateRuleSet :one
UPDATE rules.rule_set
   SET name = $1,
       status = $2
 WHERE tenant_id = $3
   AND id = $4
   AND row_version = $5
RETURNING row_version
`

type UpdateRuleSetParams struct {
	Name       string
	Status     string
	TenantID   uuid.UUID
	ID         uuid.UUID
	RowVersion int64
}

// platform.tg_touch_row bumps row_version and updated_at, so this statement never assigns
// them. The code, the domain and the purpose are absent: they are what the set is, and
// every published version was written against them.
func (q *Queries) UpdateRuleSet(ctx context.Context, arg UpdateRuleSetParams) (int64, error) {
	row := q.db.QueryRow(ctx, updateRuleSet,
		arg.Name,
		arg.Status,
		arg.TenantID,
		arg.ID,
		arg.RowVersion,
	)
	var row_version int64
	err := row.Scan(&row_version)
	return row_version, err
}

